import sqlite3

def salvar_cache(chave, payload):
    conexao = sqlite3.connect(':memory:')
    cursor = conexao.cursor()
    cursor.execute(
        'CREATE TABLE cache_api (chave TEXT PRIMARY KEY, payload TEXT, atualizado_em TEXT)'
    )
    cursor.execute(
        'INSERT INTO cache_api (chave, payload, atualizado_em) VALUES (?, ?, ?)',
        (chave, payload, '2024-09-30 08:00:00'),
    )
    conexao.commit()
    return cursor.execute('SELECT chave, payload FROM cache_api').fetchall()

